return {["fb02_01"]={["dsc"]=[[这里是衡阳回雁楼，是本地最大的酒楼。往日这时已经十分忙碌的酒楼今天却有点异样。一个年近四十的白衣汉子，正端坐自饮，桌面横放着一把快刀，旁边却坐着一个小尼姑，满脸忧急愁苦之色，容貌却十分秀丽。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb02_01]],["item1"]=[[fb02item_8]],["item2"]=[[fb02item_8]],["name"]=[[回雁楼]],["permission"]=2,["role1"]=[[fb02r01_1]],["role2"]=[[fb02r01_2]],["role3"]=[[fb02r01_3]],["roomBgm"]=[[chalou]],["roomBgmRule"]=1,["spaceTime"]=0,["stepMusic"]=[[mudiban]],["up"]=[[fb02_03]],["visible"]=1},["fb02_02"]={["BgmDown"]=1,["down"]=[[fb02_94]],["dsc"]=[[这里是南岭的一个山口。南面是岭南的大镇佛山，北面是湖南的地界。岭南广东富庶繁盛，颇有豪侠之士。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb02_02]],["item1"]=[[digongquest02]],["item2"]=[[2021xccdtrigger01]],["name"]=[[南岭山口]],["permission"]=1,["role1"]=[[fb02r02_1]],["role2"]=[[fb02r02_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb02_05]],["visible"]=1},["fb02_03"]={["BgmDown"]=1,["down"]=[[fb02_01]],["dsc"]=[[这里是衡阳县城的一间小店，卖些简单的饮食，专门赚那些游客的钱。]],["enterable"]=1,["id"]=[[fb02_03]],["name"]=[[小店]],["permission"]=2,["role1"]=[[fb02r03_1]],["role2"]=[[fb02r03_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb02_07]],["visible"]=1},["fb02_04"]={["dsc"]=[[你一走进来，就闻到一股茶香沁入心脾，精神为之一爽。几张八仙桌一字排开，坐满了客人，或高声谈笑，或交头接耳。你要想打听江湖掌故和谣言，这里是个好所在。]],["enterable"]=1,["id"]=[[fb02_04]],["name"]=[[衡阳茶馆]],["permission"]=2,["role1"]=[[fb02r04_1]],["role2"]=[[fb02r04_2]],["role3"]=[[QXr04_1]],["roomBgm"]=[[chalou]],["roomBgmRule"]=1,["spaceTime"]=0,["stepMusic"]=[[mudiban]],["up"]=[[fb02_08]],["visible"]=1},["fb02_05"]={["BgmDown"]=1,["down"]=[[fb02_02]],["dsc"]=[[这里是一条林间大道。这里是湖南境内。南边通向南岭的一个山口。路东隐隐可以看到一角城墙。西面是一座猛恶山林。]],["enterable"]=1,["fightBackground"]=[[森林外]],["id"]=[[fb02_05]],["name"]=[[林间大道]],["permission"]=1,["right"]=[[fb02_06]],["role1"]=[[fb02r05_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb02_10]],["visible"]=1},["fb02_06"]={["BgmDown"]=1,["dsc"]=[[你走在一条尘土飞扬的黄土路上，两旁是阴森森的树林。东面不远就是衡阳县城了。往西是另外一条大道。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb02_06]],["left"]=[[fb02_05]],["name"]=[[黄土路]],["permission"]=1,["right"]=[[fb02_07]],["role1"]=[[fb02r06_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb02_07"]={["down"]=[[fb02_03]],["dsc"]=[[你走在碎石铺就的狭小街道上。街上时常有人持剑疾行，似乎这里出了啥事了。南边是一家小店，北面一座大宇巍峨，重檐叠瓦，门口彩灯高悬，管家家丁好像都是武林中人。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb02_07]],["left"]=[[fb02_06]],["name"]=[[衡阳西街]],["permission"]=1,["right"]=[[fb02_08]],["role1"]=[[fb02r07_1]],["role2"]=[[fb02r07_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb02_12]],["visible"]=1},["fb02_08"]={["down"]=[[fb02_04]],["dsc"]=[[这里就是衡阳县城。衡阳地处偏远，显见远不如中原繁华了。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb02_08]],["left"]=[[fb02_07]],["name"]=[[衡阳城]],["permission"]=2,["right"]=[[fb02_09]],["role1"]=[[fb02r08_1]],["role2"]=[[fb02r08_2]],["role3"]=[[fb02r08_3]],["role4"]=[[fb02r08_4]],["stepMusic"]=[[mudiban]],["visible"]=1},["fb02_09"]={["BgmDown"]=1,["dsc"]=[[你走在一条尘土飞扬的黄土路上，两旁是阴森森的树林。西面不远就是衡阳县城了。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb02_09]],["left"]=[[fb02_08]],["name"]=[[黄土路]],["permission"]=2,["rightUp"]=[[fb02_13]],["role1"]=[[fb02r09_1]],["role2"]=[[fb02r09_2]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb02_10"]={["BgmDown"]=1,["down"]=[[fb02_05]],["dsc"]=[[这里是一条林间大道，在树丛中蜿蜒。这里是湖南境内。北边是湖北。路边有可供路人休息的小茶亭。]],["enterable"]=1,["fightBackground"]=[[森林外]],["id"]=[[fb02_10]],["name"]=[[林间大道]],["permission"]=1,["right"]=[[fb02_11]],["role1"]=[[fb02r10_1]],["role2"]=[[fb02r10_2]],["role3"]=[[fb02r10_3]],["stepMusic"]=[[shulin]],["up"]=[[fb02_14]],["visible"]=1},["fb02_11"]={["BgmDown"]=1,["dsc"]=[[这是一家路边的小茶亭，赶山路的人常在此处歇歇脚。亭子里有几张桌子和几支条凳。周围是一片树林。]],["enterable"]=1,["id"]=[[fb02_11]],["left"]=[[fb02_10]],["name"]=[[茶亭]],["permission"]=2,["role1"]=[[fb02r11_1]],["role2"]=[[QXr11_a1]],["role3"]=[[QXr11_2]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb02_12"]={["down"]=[[fb02_07]],["dsc"]=[[这里是刘府大门。刘府的主人曾是衡山宗中赫赫有名的人物，地位仅次于掌门。今天兴许刘府有事吧，大门紧闭，管家家丁也异常紧张。只有檐下写有“刘府”二字的大红灯笼中忽闪晃动的烛光才显出点活人气。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb02_12]],["item1"]=[[fb02item_10]],["name"]=[[刘府大门]],["permission"]=1,["role1"]=[[fb02r12_1]],["role2"]=[[fb02r12_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb02_16]],["visible"]=1},["fb02_13"]={["BgmDown"]=1,["dsc"]=[[你走在一条尘土飞扬的黄土路上，两旁是阴森森的树林。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb02_13]],["leftDown"]=[[fb02_09]],["leftUp"]=[[fb02_18]],["name"]=[[黄土路]],["permission"]=2,["role1"]=[[fb02r13_1]],["role2"]=[[fb02r13_2]],["role3"]=[[fb02r13_3]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb02_14"]={["BgmDown"]=1,["down"]=[[fb02_10]],["dsc"]=[[这里是一条林间大道，在树丛中蜿蜒。这里是湖北境内。南边是湖南。]],["enterable"]=1,["fightBackground"]=[[森林外]],["id"]=[[fb02_14]],["item1"]=[[21masktrigger01]],["name"]=[[林间大道]],["permission"]=1,["role1"]=[[ever14_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb02_19]],["visible"]=1},["fb02_15"]={["BgmDown"]=1,["dsc"]=[[这是间整洁的客房，因门窗常闭着，光线很昏暗。两边放着几张收拾得舒舒服服的大床，看着就让人想睡觉。床边椅子上坐着一个黑衣老人，神情显得极为关切。老人膝上靠着一个小女孩。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb02_15]],["name"]=[[客房]],["permission"]=2,["right"]=[[fb02_16]],["role1"]=[[fb02r15_1]],["role2"]=[[fb02r15_2]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb02_16"]={["down"]=[[fb02_12]],["dsc"]=[[刘府大院里现在挤着很多江湖豪客，原来今天正是刘府主人刘老爷金盆洗手的好日子。刘老爷子在衡阳人缘很好，来捧场的自然不少，大院里已摆了很多张桌子，杯筷往来，很是热闹。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb02_16]],["left"]=[[fb02_15]],["name"]=[[刘府大院]],["permission"]=1,["right"]=[[fb02_17]],["role1"]=[[fb02r16_1]],["role2"]=[[fb02r16_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb02_21]],["visible"]=1},["fb02_17"]={["BgmDown"]=1,["dsc"]=[[这里是刘府中用来练功的地方。有几个人正在专心致致地练武，有几个手持兵器，在互相拆招。身法灵动，犹如穿花蝴蝶一般，你不禁看花了眼，别的人则坐在地上的蒲团上苦练内力。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb02_17]],["item1"]=[[fb02item_9]],["left"]=[[fb02_16]],["name"]=[[练功房]],["permission"]=2,["stepMusic"]=[[mudiban]],["visible"]=1},["fb02_18"]={["BgmDown"]=1,["dsc"]=[[你走在一条尘土飞扬的黄土路上，两旁是阴森森的树林。这里向北通往扬州，往南就进入湖南地界了。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb02_18]],["name"]=[[黄土路]],["permission"]=2,["rightDown"]=[[fb02_13]],["rightUp"]=[[fb02_24]],["role1"]=[[fb02r18_1]],["role2"]=[[fb02r18_2]],["role3"]=[[fb02r02_3]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb02_19"]={["BgmDown"]=1,["down"]=[[fb02_14]],["dsc"]=[[这里是一条林间小道，在树丛中蜿蜒。西北方连着一条黄土路，南面的道路要宽一些。]],["enterable"]=1,["fightBackground"]=[[森林外]],["id"]=[[fb02_19]],["name"]=[[林间道]],["permission"]=1,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb02_20"]={["BgmDown"]=1,["dsc"]=[[这儿是西厢房，这儿整理得干干净净，窗外露出点绿绿的枝叶，家具上一尘不染，地上铺着很大块的青砖，一点灰尘也不沾。刘府的小孩们不知在这里悄悄说着什么。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb02_20]],["name"]=[[西厢房]],["permission"]=2,["right"]=[[fb02_21]],["role1"]=[[fb02r20_1]],["role2"]=[[fb02r20_2]],["role3"]=[[fb02r20_3]],["role4"]=[[fb02r20_4]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb02_21"]={["down"]=[[fb02_16]],["dsc"]=[[刘府大厅里就安静多了。主人坐在太师椅上，神色抑郁。大厅正中放着一张茶几，上面铺了锦缎。一只金光灿烂、径长尺半的黄金盆子，放在茶几之上，盆中已盛满了清水。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb02_21]],["left"]=[[fb02_20]],["name"]=[[刘府大厅]],["permission"]=1,["right"]=[[fb02_22]],["role1"]=[[fb02r21_1]],["role2"]=[[fb02r21_2]],["role3"]=[[fb02r21_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb02_23]],["visible"]=1},["fb02_22"]={["BgmDown"]=1,["dsc"]=[[这儿是东厢房，这儿整理得干干净净，窗外露出点绿绿的枝叶，家具上一尘不染，地上铺着很大块的青砖，一点灰尘也不沾。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb02_22]],["left"]=[[fb02_21]],["name"]=[[东厢房]],["permission"]=2,["role1"]=[[fb02r22_1]],["role2"]=[[fb02r22_2]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb02_23"]={["BgmDown"]=1,["down"]=[[fb02_21]],["dsc"]=[[这里是膳厅，刘府人用膳的地方。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb02_23]],["item1"]=[[fb02item_17]],["name"]=[[膳厅]],["permission"]=2,["role1"]=[[fb02r23_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb02_24"]={["dsc"]=[[这是一条松林中的小路，两边长满参天的红松树，只能看见一线天空。]],["enterable"]=1,["fightBackground"]=[[森林内]],["id"]=[[fb02_24]],["leftDown"]=[[fb02_18]],["name"]=[[松林小道]],["permission"]=2,["role1"]=[[2019qxcdg1a]],["role2"]=[[2019qxcdg1b]],["stepMusic"]=[[jiaobu]],["up"]=[[fb02_25]],["visible"]=1},["fb02_25"]={["down"]=[[fb02_24]],["dsc"]=[[这是一条松林中