55]],["visible"]=1},["fb02_48"]={["down"]=[[fb02_40]],["dsc"]=[[站在路中阵阵酒香从南面传来。]],["enterable"]=1,["fightBackground"]=[[村庄室外]],["id"]=[[fb02_48]],["left"]=[[fb02_47]],["name"]=[[华亭村道]],["permission"]=2,["right"]=[[fb02_49]],["role1"]=[[fb02r48_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb02_56]],["visible"]=1},["fb02_49"]={["dsc"]=[[西边有客栈酒馆，东边则是当铺豆腐铺。]],["enterable"]=1,["fightBackground"]=[[村庄室外]],["id"]=[[fb02_49]],["item1"]=[[fb02item_18]],["item2"]=[[2021xccdtrigger02]],["left"]=[[fb02_48]],["name"]=[[华亭村中心]],["permission"]=2,["right"]=[[fb02_50]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb02_50"]={["down"]=[[fb02_42]],["dsc"]=[[向前便是豆腐铺，想吃豆腐可以去那。]],["enterable"]=1,["fightBackground"]=[[村庄室外]],["id"]=[[fb02_50]],["left"]=[[fb02_49]],["name"]=[[华亭村道]],["permission"]=2,["right"]=[[fb02_51]],["stepMusic"]=[[jiaobu]],["up"]=[[fb02_57]],["visible"]=1},["fb02_51"]={["down"]=[[fb02_43]],["dsc"]=[[恶人村的东面，前方有一口清泉可以饮用解渴。]],["enterable"]=1,["fightBackground"]=[[村庄室外]],["id"]=[[fb02_51]],["left"]=[[fb02_50]],["name"]=[[华亭村东首]],["permission"]=2,["right"]=[[fb02_52]],["stepMusic"]=[[jiaobu]],["up"]=[[fb02_58]],["visible"]=1},["fb02_52"]={["dsc"]=[[前方便是一座桃园，虽为成熟，但桃花已开的异常艳丽。]],["enterable"]=1,["fightBackground"]=[[村庄室外]],["id"]=[[fb02_52]],["left"]=[[fb02_51]],["leftUp"]=[[fb02_59]],["name"]=[[村道尽头]],["permission"]=2,["right"]=[[fb02_53]],["rightDown"]=[[fb02_44]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb02_53"]={["dsc"]=[[眼前豁然开朗，你轻松地走在果园边的小路上。路上落英缤纷，两边是桃树林，盛开着粉红的桃花，红云一片，望不到边。还可以看蜜蜂嗡嗡地在花间飞上飞下忙个不停，间或传来猿猴的叽咋声。]],["enterable"]=1,["fightBackground"]=[[森林内]],["id"]=[[fb02_53]],["left"]=[[fb02_52]],["name"]=[[果园]],["permission"]=2,["rightUp"]=[[fb02_60]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb02_54"]={["dsc"]=[[村中人养殖的鱼塘，看来是不错的垂钓之地。]],["enterable"]=1,["fightBackground"]=[[村庄室外]],["id"]=[[fb02_54]],["item1"]=[[fb02item_24]],["item2"]=[[fb02item_21]],["item3"]=[[2020qixihd]],["name"]=[[村外鱼塘]],["permission"]=2,["rightDown"]=[[fb02_46]],["rightUp"]=[[fb02_61]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb02_55"]={["down"]=[[fb02_47]],["dsc"]=[[这里是块菜地，由于长期得不到良好的照顾，菜地里杂草丛生，种的菜都长势不好，蔫蔫的，地都荒了。]],["enterable"]=1,["id"]=[[fb02_55]],["item1"]=[[fb02item_27]],["name"]=[[菜田]],["permission"]=2,["role1"]=[[fb02r55_1]],["role2"]=[[fb02r55_2]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb02_56"]={["down"]=[[fb02_48]],["dsc"]=[[破旧的客栈，门上牌匾刻着娇娇客栈，屋内只有一粗壮男子搂着一名娇小女子窃窃私语。]],["enterable"]=1,["id"]=[[fb02_56]],["item1"]=[[fb02item_14]],["name"]=[[娇娇客栈]],["permission"]=2,["role1"]=[[fb02r56_1]],["role2"]=[[fb02r56_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb02_62]],["visible"]=1},["fb02_57"]={["down"]=[[fb02_50]],["dsc"]=[[装饰豪华的当铺，进进出出的人群向你展示这店铺兴旺的生意。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb02_57]],["name"]=[[同富当铺]],["permission"]=2,["role1"]=[[fb02r57_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb02_63]],["visible"]=1},["fb02_58"]={["down"]=[[fb02_51]],["dsc"]=[[这边是村中人称赞的豆腐铺，看样子也知道开了有些年头了。]],["enterable"]=1,["fightBackground"]=[[村庄室外]],["id"]=[[fb02_58]],["name"]=[[清风豆腐铺]],["permission"]=2,["role1"]=[[fb02r58_1]],["role2"]=[[fb02r58_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb02_76]],["visible"]=1},["fb02_59"]={["dsc"]=[[这是一片郁郁葱葱的竹林，这片竹林中竹子种类繁多，细细看来，有状若罗汉肚的罗汉竹，有隐隐红点的湘妃竹，有笔直粗壮的楠竹..竹叶的清香，令人置其中，心旷神怡。竹林东南，有一条青石砌成的小路。]],["enterable"]=1,["fightBackground"]=[[森林内]],["id"]=[[fb02_59]],["name"]=[[竹林]],["permission"]=2,["rightDown"]=[[fb02_52]],["stepMusic"]=[[jiaobu]],["up"]=[[fb02_64]],["visible"]=1},["fb02_60"]={["dsc"]=[[眼前豁然开朗，你轻松地走在果园边的小路上。路上落英缤纷，两边是桃树林，盛开着粉红的桃花，红云一片，望不到边。还可以看蜜蜂嗡嗡地在花间飞上飞下忙个不停，间或传来猿猴的叽咋声。]],["enterable"]=1,["fightBackground"]=[[森林外]],["id"]=[[fb02_60]],["leftDown"]=[[fb02_53]],["name"]=[[果园]],["permission"]=2,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb02_61"]={["dsc"]=[[这里是一片草地，草间散布着一些奇花，微风吹过，芬芳扑鼻。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb02_61]],["leftDown"]=[[fb02_54]],["name"]=[[青草地]],["permission"]=2,["rightUp"]=[[fb02_65]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb02_62"]={["down"]=[[fb02_56]],["dsc"]=[[娇娇客栈仅有的一间客房，即便是这样娇娇客栈一般也住不满人。