["permission"]=2,["right"]=[[fb02_86]],["rightDown"]=[[fb02_81]],["rightUp"]=[[fb02_90]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb02_86"]={["dsc"]=[[阴暗且寒冷的洞穴，可闻到青苔的气味，洞顶不时有水滴滴落，]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb02_86]],["item1"]=[[20bafangjg]],["item2"]=[[20bafangbaishe2]],["left"]=[[fb02_85]],["name"]=[[阴冷洞穴]],["permission"]=2,["right"]=[[fb02_87]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb02_87"]={["dsc"]=[[洞穴的中段，洞道开始收窄，两侧洞壁似有锤砸斧砍的痕迹。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb02_87]],["item1"]=[[20bafangjg]],["item2"]=[[20bafangbaishe1]],["left"]=[[fb02_86]],["name"]=[[洞穴中段]],["permission"]=2,["right"]=[[fb02_88]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb02_88"]={["dsc"]=[[洞穴的深处，几乎伸手不见五指，地面极为湿滑，稍不小心便会滑倒。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb02_88]],["left"]=[[fb02_87]],["name"]=[[洞穴深处]],["permission"]=2,["right"]=[[fb02_89]],["role1"]=[[20bafangyr1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb02_89"]={["dsc"]=[[洞穴的尽头，一片漆黑，散发着一股金属锈蚀的气味。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb02_89]],["item1"]=[[20bafangjl]],["left"]=[[fb02_88]],["name"]=[[洞穴尽头]],["permission"]=2,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb02_90"]={["dsc"]=[[闷热且潮湿的洞穴，角落处堆着几具已近腐烂的尸体。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb02_90]],["item1"]=[[20bafangdsfj]],["leftDown"]=[[fb02_85]],["name"]=[[潮湿洞穴]],["permission"]=2,["right"]=[[fb02_91]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb02_91"]={["dsc"]=[[极为阴暗且狭窄的洞穴，仅可容一人通过，洞穴顶部极为平整，似乎被人为开凿过。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb02_91]],["item1"]=[[20bafangjg]],["item2"]=[[20bafangbaishe2]],["left"]=[[fb02_90]],["name"]=[[阴暗洞穴]],["permission"]=2,["right"]=[[fb02_92]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb02_92"]={["dsc"]=[[寒冷无比的洞穴，寒风凛冽，在此洞穴前进一步都极为困难。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb02_92]],["left"]=[[fb02_91]],["name"]=[[寒冷洞穴]],["permission"]=2,["right"]=[[fb02_93]],["role1"]=[[20bafangdmz1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb02_93"]={["dsc"]=[[伸手不见五指的洞穴，阴风阵阵吹过，让人不禁心中生寒。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb02_93]],["item1"]=[[20bafangjl]],["left"]=[[fb02_92]],["name"]=[[荒凉洞穴]],["permission"]=2,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb02_94"]={["dsc"]=[[这里一片南岭山脉，群山高低起伏，一望无际。群山南接岭南大镇佛山，北通湖南地界，山内万木争荣，卧虎藏龙。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb02_94]],["item1"]=[[digongitem01]],["name"]=[[南岭山脉]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb02_02]],["visible"]=0},["fb02_95"]={["dsc"]=[[这是一条窄小的通道。通道似是某人用工具仓促开凿的，通道的尽头是一个不大的洞口，新鲜的空气和温暖的阳光不断从洞口灌入，从洞口出去应该就回到地面了。]],["enterable"]=1,["id"]=[[fb02_95]],["item1"]=[[dgwp10a]],["name"]=[[出口]],["role1"]=[[digongqz03]],["role2"]=[[digongqz01_5]],["roomBgm"]=[[jiaowai]],["roomBgmRule"]=1,["spaceTime"]=0,["stepMusic"]=[[jiaobu]],["visible"]=1}}00000000000